export const LED_PALETTE = Object.freeze([{"id": 0, "name": "red", "hex": "#ff2a1f"}, {"id": 1, "name": "blue", "hex": "#2a6bff"}, {"id": 2, "name": "yellow", "hex": "#ffd21f"}, {"id": 3, "name": "green", "hex": "#23e05a"}, {"id": 4, "name": "purple", "hex": "#a04cff"}, {"id": 5, "name": "teal", "hex": "#17e0d0"}, {"id": 6, "name": "white", "hex": "#ffffff"}, {"id": 7, "name": "pink", "hex": "#ff4fb0"}, {"id": 8, "name": "orange", "hex": "#ff8a1f"}].map(r => Object.freeze(r)));
/** The $GLED colour tokens that are dark (poolgauge.py DARK_INDICES), outside LED_PALETTE's ids. */
export const LED_DARK_INDICES = Object.freeze([9, 10]);

